record.field:
if payroll.ua.time_ratio >= 0:
    result = tools.r2(contract.wage * payroll.ua.fte * payroll.ua.time_ratio, 2)
else:
    days = worked_days.WORK100.number_of_days if worked_days.WORK100 else 0.0
    for code, line in worked_days.dict.items():
        if code != 'WORK100' and line:
            days -= abs(line.number_of_days)
    total = payroll.ua.month_workdays or days or 1.0
    result = tools.r2(contract.wage * payroll.ua.fte * max(min(days, total), 0.0) / total, 2)
